SELECT DATE_TRUNC('QUARTER', signup_date) AS quarter_start, SUM(credit_limit) AS total_credit_limit, SORT_ARRAY(COLLECT_SET(segment)) AS segment_list, COUNT(CASE WHEN city = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, STDDEV_SAMP(age) AS age_stddev, AVG(credit_limit) AS avg_credit_limit, MAX(age) FILTER (WHERE country = 'JP') AS jp_max_age FROM customers GROUP BY quarter_start ORDER BY age_stddev DESC NULLS FIRST;
